import { test } from 'node:test';
import { strictEqual, throws } from 'node:assert';
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { runInNewContext } from 'node:vm';
import { renderDoxyfile, renderPage, repositoryName } from './doxyfile.ts';
import { decodeEntities, unescapeHeaders } from './unescape.ts';
import { libraryVersions } from './metadata_version.ts';

test('Doxyfile markers are substituted and required', () => {
  strictEqual(renderDoxyfile('PROJECT_NUMBER=__VERSION__\nPROJECT_BRIEF=__DESCRIPTION__\nGENERATE_HTML=__GENERATE_HTML__\nGENERATE_XML=__GENERATE_XML__\nINPUT=__SOURCE_ROOTS__\n', {
    version: 'v1.4.1', description: 'A | B', html: 'YES', xml: 'NO', sourceRoots: '.doxy-build/source/include/jh',
  }), 'PROJECT_NUMBER=v1.4.1\nPROJECT_BRIEF=A \\| B\nGENERATE_HTML=YES\nGENERATE_XML=NO\nINPUT=.doxy-build/source/include/jh\n');
  throws(() => renderDoxyfile('', { version: '', description: '', html: '', xml: '', sourceRoots: '' }));
  strictEqual(repositoryName('https://github.com/JeongHan-Bae/JH-Toolkit/'), 'JeongHan-Bae/JH-Toolkit');
  strictEqual(renderPage('__TOOLKIT_VERSION__ __CUCUMBER_VERSION__ __TINY_TEST_VERSION__', {
    'jh-toolkit': '1.4.1', 'jh-simple-cucumber': '0.1.0', 'jh-tiny-test': '0.1.0',
  }), 'v1.4.1 v0.1.0 v0.1.0');
});

test('entity decoding leaves escaped and unknown references alone', () => {
  strictEqual(decodeEntities('A &lt; B &#64; C \\&gt; D &unknown;'), 'A < B @ C \\&gt; D &unknown;');
});

test('unescape writes only to the ignored Doxygen source copy', () => {
  const root = mkdtempSync(join(tmpdir(), 'jh-doxy-'));
  try {
    mkdirSync(join(root, 'include', 'jh'), { recursive: true });
    mkdirSync(join(root, 'simple-cucumber', 'include', 'jh', 'test', 'cucumber'), { recursive: true });
    mkdirSync(join(root, 'simple-cucumber', 'gherkin', 'include', 'jh', 'test', 'cucumber'), { recursive: true });
    mkdirSync(join(root, 'tiny-test', 'include', 'jh', 'test', 'tiny_test'), { recursive: true });
    const original = join(root, 'include', 'jh', 'sample.h');
    writeFileSync(original, '/// &lt;code&gt;\n');
    const cucumber = join(root, 'simple-cucumber', 'include', 'jh', 'test', 'cucumber', 'sample.hpp');
    writeFileSync(cucumber, '/// &#64;brief\n');
    unescapeHeaders(root);
    strictEqual(readFileSync(original, 'utf8'), '/// &lt;code&gt;\n');
    strictEqual(readFileSync(join(root, '.doxy-build/source', 'include', 'jh', 'sample.h'), 'utf8'), '/// <code>\n');
    strictEqual(readFileSync(cucumber, 'utf8'), '/// &#64;brief\n');
    strictEqual(readFileSync(join(root, '.doxy-build/source', 'simple-cucumber', 'include', 'jh', 'test', 'cucumber', 'sample.hpp'), 'utf8'), '/// @brief\n');
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test('version comes from metadata_scripts', () => {
  const root = mkdtempSync(join(tmpdir(), 'jh-metadata-'));
  try {
    mkdirSync(join(root, '.github', 'workflows', 'metadata_scripts'), { recursive: true });
    writeFileSync(join(root, '.github', 'workflows', 'metadata_scripts', 'get_version.ts'), 'console.log(JSON.stringify({"jh-toolkit":"1.4.1","jh-simple-cucumber":"0.1.0","jh-tiny-test":"0.1.0"}));\n');
    strictEqual(libraryVersions(root)['jh-toolkit'], '1.4.1');
    strictEqual(libraryVersions(root)['jh-simple-cucumber'], '0.1.0');
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test('footer selects a skill icon only on the three library entry pages', () => {
  const footer = readFileSync(new URL('./settings/footer.html', import.meta.url), 'utf8');
  const versions = { 'jh-toolkit': '1.4.1', 'jh-simple-cucumber': '0.1.0', 'jh-tiny-test': '0.2.0' };
  const script = renderPage(footer, versions).match(/<script>([\s\S]*?)<\/script>/)?.[1]?.replaceAll('$relpath$', '');
  if (!script) throw new Error('Footer icon script is missing');
  for (const [page, expectedIcon, expectedText] of [
    ['toolkit_library.html', 'skill.svg', 'JH-Toolkit v1.4.1 · Generated by Doxygen'],
    ['cucumber_library.html', 'simple-cucumber.skill.svg', 'JH-Simple-Cucumber v0.1.0 · Generated by Doxygen'],
    ['tiny_test_library.html', 'tiny-test.skill.svg', 'JH-Tiny-Test v0.2.0 · Generated by Doxygen'],
    ['index.html', 'Ojing.svg', 'JH-Toolkit v1.4.1 · Generated by Doxygen'],
  ]) {
    const logo = { src: 'Ojing.svg', alt: 'Ojing' };
    const text = { textContent: 'JH-Toolkit v1.4.1 · Generated by Doxygen' };
    runInNewContext(script, {
      window: { location: { pathname: `/${page}` } },
      document: { getElementById: (id: string) => id === 'library-footer-logo' ? logo : text },
    });
    strictEqual(logo.src, expectedIcon);
    strictEqual(text.textContent, expectedText);
  }
});
